import math

def count_divisors(n):
    if n == 1:
        return 1
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic(tau_n):
    """Checks if tau_n is twice an odd integer."""
    if tau_n <= 0:
        return False
    # Check if tau_n / 2 is an integer and is odd.
    if tau_n % 2 != 0:
        return False
    m = tau_n // 2
    return m % 2 != 0

def find_132nd_exotic():
    count = 0
    n = 1
    exotic_numbers = []

    # We need to find the 132nd number. Let's search up to a reasonable limit first.
    # Based on the density of primes (which are exotic), 10000 should be safe.
    max_n = 25000 

    while count < 132 and n <= max_n:
        tau_n = count_divisors(n)
        if is_exotic(tau_n):
            count += 1
            exotic_numbers.append(n)
        n += 1

    if count < 132:
        print(f"Warning: Stopped at {max_n}, only found {count} exotic numbers.")
    else:
        print(f"Found {count} exotic numbers.")
        print(f"The 132nd exotic number is: {exotic_numbers[131]}")
        # Print the list up to the 132nd to verify the count
        print(f"List length: {len(exotic_numbers)}")

