def find_exotic_integers(target_count):
    exotic_list = []
    n = 1
    while len(exotic_list) < target_count:
        # We only consider composite numbers n.
        # Numbers with 6 divisors must be composite since the smallest number with 6 divisors is 12 (tau(1) is undefined/1).

        # If tau(n) = 6, it is exotic (since 6 = 2 * 3, and 3 is odd).
        if count_divisors(n) == 6:
            exotic_list.append(n)
        n += 1

    return exotic_list

